/**
 * Big Plan Mode — the node map.
 *
 * "Build" in Plan Mode means something narrower than building an app: it maps
 * the design the user drew on the canvas onto real files and folders — one file
 * per node, named and wired exactly as a later build would name and wire them —
 * while generating NO code. The design gets a shape on disk the moment it is
 * ready to have one, and the user can see what they have actually specified.
 *
 * Two properties this deliberately holds:
 *
 *  • **No model is involved.** Every byte here is derived from the graph with
 *    pure functions, so mapping a design costs nothing, cannot fail on a dead
 *    LLM, and is byte-identical for the same design. It also means nothing here
 *    can reach the training set: verified-generation capture is keyed to
 *    FileGenerator runs, and this never runs FileGenerator.
 *
 *  • **The names come from the build's own helpers** (`labelToFileName`,
 *    `getFileExtension` from the FileGenerator). A map whose filenames drifted
 *    from the build's would be a map of a different program.
 *
 * Each mapped file carries a comment header with the node's declared purpose,
 * the co-worker questions answered for it, and its dependencies — so opening
 * any file tells you what it is for before any code exists.
 */
import { writeFileSync, readFileSync, mkdirSync, existsSync, unlinkSync } from 'fs';
import path from 'path';
import { PLANS_DIR, safePlanName } from './planFile.js';
import { labelToFileName, getFileExtension } from '../layers/fileGenerator.js';
/** Comment prefix for a language, so the header is valid where it is written. */
function commentPrefix(language) {
    const l = (language || '').toLowerCase();
    if (l === 'python' || l === 'ruby')
        return '#';
    return '//';
}
/** The language a node's file is written as: its own, else the design default. */
function languageOf(node, fallback) {
    return (node.language || fallback || 'typescript').toLowerCase();
}
/**
 * Turn labels into unique filenames. Two nodes named "Auth" and "auth" would
 * otherwise map onto one file and silently delete a node's design.
 */
function uniqueFileNames(nodes, fallbackLang) {
    const used = new Set();
    const out = new Map();
    for (const node of nodes) {
        const base = labelToFileName(node.label || 'untitled');
        const ext = getFileExtension(languageOf(node, fallbackLang));
        let candidate = `${base}.${ext}`;
        let n = 2;
        while (used.has(candidate)) {
            candidate = `${base}-${n}.${ext}`;
            n += 1;
        }
        used.add(candidate);
        out.set(node.id, candidate);
    }
    return out;
}
function headerFor(node, record, fallbackLang) {
    const c = commentPrefix(languageOf(node, fallbackLang));
    const line = (s = '') => (s ? `${c} ${s}` : c);
    const answers = (node.qa || []).filter((qa) => qa?.a);
    const lines = [
        line(`${node.label} — ${node.type} · ${languageOf(node, fallbackLang)}`),
        line(),
        line(`Purpose: ${(node.description || '').trim() || '(no purpose declared yet)'}`),
    ];
    if (answers.length) {
        lines.push(line());
        lines.push(line('Design questions answered (Big Plan Mode co-worker):'));
        for (const qa of answers) {
            lines.push(line(`  Q: ${(qa.q || '').trim()}`));
            lines.push(line(`  A: ${(qa.a || '').trim()}`));
        }
    }
    lines.push(line());
    lines.push(line(`Depends on: ${record.dependsOn.length ? record.dependsOn.join(', ') : '(nothing)'}`));
    lines.push(line(`Used by: ${record.dependedOnBy.length ? record.dependedOnBy.join(', ') : '(nothing yet)'}`));
    lines.push(line());
    lines.push(line('No code yet. This file is the design\'s shape, mapped from the canvas —'), line('generated by Big Plan Mode, never by the model.'));
    return `${lines.join('\n')}\n`;
}
function wiringDoc(record) {
    const lines = [
        `# Wiring map — ${record.projectName}`,
        '',
        record.goal ? `**What it is:** ${record.goal}` : '_(no statement of intent yet)_',
        '',
        `Mapped from the canvas design: ${record.files.length} file${record.files.length === 1 ? '' : 's'}, no code generated.`,
        '',
        '| file | node | type | language | depends on |',
        '| --- | --- | --- | --- | --- |',
    ];
    for (const f of record.files) {
        lines.push(`| \`${f.file}\`${f.entry ? ' **(entry)**' : ''} | ${f.label} | ${f.type} | ${f.language} | ${f.dependsOn.length ? f.dependsOn.map((d) => `\`${d}\``).join(', ') : '—'} |`);
    }
    const unwired = record.files.filter((f) => !f.dependsOn.length && !f.dependedOnBy.length);
    lines.push('', '## Not wired to anything yet', '');
    if (unwired.length === 0) {
        lines.push('Every file is part of the design\'s wiring.');
    }
    else {
        for (const f of unwired)
            lines.push(`- \`${f.file}\` (${f.label})`);
    }
    lines.push('');
    return lines.join('\n');
}
/**
 * Write the design's node map into data/plans/<name>/map/.
 *
 * Rewrites cleanly: files the previous map created and the design no longer
 * needs are removed, and only files this mapper wrote (as listed in the
 * previous map.json) are ever touched — anything else in that folder is left
 * alone rather than swept.
 */
export function writePlanMap(data) {
    const projectName = (data.projectName || 'Untitled Project').trim();
    const dirName = safePlanName(projectName);
    const planDir = path.join(PLANS_DIR, dirName);
    const mapDir = path.join(planDir, 'map');
    // The master node is the app itself, so it sets the default language for
    // nodes that never picked one.
    const fallbackLang = data.nodes.find((n) => n.isMaster)?.language ||
        data.nodes.find((n) => n.language)?.language ||
        'typescript';
    const nodes = data.nodes.filter((n) => n && n.id);
    const edges = (data.edges || []).filter((e) => e && nodes.some((n) => n.id === e.source) && nodes.some((n) => n.id === e.target));
    const names = uniqueFileNames(nodes, fallbackLang);
    const files = nodes.map((node) => {
        const file = names.get(node.id);
        const dependsOn = edges
            .filter((e) => e.target === node.id)
            .map((e) => names.get(e.source))
            .filter((f) => f && f !== file);
        const dependedOnBy = edges
            .filter((e) => e.source === node.id)
            .map((e) => names.get(e.target))
            .filter((f) => f && f !== file);
        return {
            nodeId: node.id,
            label: node.label || node.id,
            type: node.type || 'logic',
            language: languageOf(node, fallbackLang),
            file,
            entry: Boolean(node.isMaster),
            dependsOn: [...new Set(dependsOn)],
            dependedOnBy: [...new Set(dependedOnBy)],
            answers: (node.qa || []).filter((qa) => qa?.a).length,
        };
    });
    mkdirSync(mapDir, { recursive: true });
    // ── Remove files the previous mapping created that the design dropped ──
    // Read from the previous map.json so only THIS mapper's output is eligible;
    // a file the user put in map/ themselves is never deleted.
    const removed = [];
    const prevMapPath = path.join(mapDir, 'map.json');
    if (existsSync(prevMapPath)) {
        try {
            const prev = JSON.parse(readFileSync(prevMapPath, 'utf-8'));
            const current = new Set(files.map((f) => f.file));
            for (const old of Array.isArray(prev?.files) ? prev.files : []) {
                const name = typeof old?.file === 'string' ? old.file : '';
                // Defence in depth: never unlink outside mapDir, even if map.json was
                // hand-edited to say "../../something".
                if (!name || current.has(name) || path.basename(name) !== name)
                    continue;
                const target = path.join(mapDir, name);
                if (existsSync(target)) {
                    unlinkSync(target);
                    removed.push(name);
                }
            }
        }
        catch {
            // A corrupt previous map is not a reason to refuse to write a new one.
        }
    }
    for (const f of files) {
        const node = nodes.find((n) => n.id === f.nodeId);
        writeFileSync(path.join(mapDir, f.file), headerFor(node, f, fallbackLang), 'utf-8');
    }
    writeFileSync(path.join(mapDir, 'wiring.md'), wiringDoc({ projectName, goal: data.goal || '', files }), 'utf-8');
    const writtenAt = new Date().toISOString();
    const record = {
        projectName,
        dirName,
        mapDir,
        entryFile: files.find((f) => f.entry)?.file || files[0]?.file || null,
        files,
        removed,
        writtenAt,
    };
    writeFileSync(path.join(mapDir, 'map.json'), JSON.stringify({ projectName, goal: data.goal || '', writtenAt, entryFile: record.entryFile, files }, null, 2), 'utf-8');
    return record;
}
/** Has this design been mapped? (Used to keep an existing map in sync.) */
export function planMapExists(projectName) {
    const dirName = safePlanName((projectName || 'Untitled Project').trim());
    return existsSync(path.join(PLANS_DIR, dirName, 'map', 'map.json'));
}
